import{_ as i,a,c as e,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Ruby 起步：对象、方法、集合与脚本","description":"从解释器执行到对象与符号、真假、方法参数、数组和Hash，建立清楚的Ruby基础。","frontmatter":{"title":"Ruby 起步：对象、方法、集合与脚本","description":"从解释器执行到对象与符号、真假、方法参数、数组和Hash，建立清楚的Ruby基础。","showdocs":{"topics":[{"id":"ruby","title":"Ruby","link":"/topics/ruby/"}],"kind":"对象与枚举","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Ruby 系统课程","summary":"从解释器执行到对象与符号、真假、方法参数、数组和Hash，建立清楚的Ruby基础。","status":"active","related":[{"title":"Ruby 惰性枚举与 IO 的有效期","link":"/programming/other-languages/ruby/plus/practice/lazy-io","kind":"开发实践","scope":"general","audience":"general"},{"title":"Ruby 方法分派：用 owner 与 super_method 定位覆盖","link":"/programming/other-languages/ruby/pro/diagnostics/method-dispatch","kind":"排错","scope":"general","audience":"general"},{"title":"Ruby 分配诊断：对象数量、存活与提前终止","link":"/programming/other-languages/ruby/pro/diagnostics/allocation","kind":"排错","scope":"general","audience":"general"},{"title":"Ruby 完整实践：Enumerable分类账、资源与诊断","link":"/programming/other-languages/ruby/plus/practice/project","kind":"开发实践","scope":"general","audience":"general"},{"title":"Ruby 的 block、Proc 与 lambda 如何返回","link":"/programming/other-languages/ruby/base/basic/blocks-callables","kind":"对象与枚举","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Ruby 对象身份、Hash 键与可变默认值","link":"/programming/other-languages/ruby/base/basic/equality-keys"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Ruby 对象身份、Hash 键与可变默认值","link":"/programming/other-languages/ruby/base/basic/equality-keys"}},"headers":[],"relativePath":"programming/other-languages/ruby/base/basic/foundations.md","filePath":"programming/other-languages/ruby/base/basic/foundations.md"}'),l={name:"programming/other-languages/ruby/base/basic/foundations.md"};function t(h,s,r,p,k,o){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="ruby-起步-对象、方法、集合与脚本" tabindex="-1">Ruby 起步：对象、方法、集合与脚本 <a class="header-anchor" href="#ruby-起步-对象、方法、集合与脚本" aria-label="Permalink to &quot;Ruby 起步：对象、方法、集合与脚本&quot;">​</a></h1><h2 id="setup" tabindex="-1">安装与第一次运行 <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;安装与第一次运行 {#setup}&quot;">​</a></h2><p>Ruby是动态类型、面向对象语言，Rails是其Web框架而非语言本身。无需先安装Rails或数据库即可学习脚本、标准库与测试。2026-10-17核对：Windows使用官方站点推荐的RubyInstaller4.0.7-1 x64便携包；Linux使用Ubuntu26.04发行版Ruby3.3.8-2ubuntu3.1。语言与Data类示例兼容3.3/4.0，发行版安全补丁不等于上游版本号同步，后续部署按官方分支维护与发行版公告核对。</p><p>Windows从<a href="https://rubyinstaller.org/downloads/" target="_blank" rel="noopener noreferrer">RubyInstaller下载</a>选择对应架构，纯脚本可解压不带Devkit的包，用PowerShell <code>&amp; &#39;D:/tools/ruby/bin/ruby.exe&#39; -v</code>；带原生扩展的gem另需编译工具，不能把纯脚本通过写成原生扩展也兼容。Linux可按<a href="https://www.ruby-lang.org/en/documentation/installation/" target="_blank" rel="noopener noreferrer">Ruby安装</a>使用发行版包，确认<code>ruby -v</code>与<code>gem env</code>来自同一环境。</p><p>hello.rb完整文件：</p><div class="language-ruby vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">puts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Hello, Ruby!&#39;</span></span></code></pre></div><p><code>ruby -c hello.rb</code>检查语法，<code>ruby hello.rb</code>输出Hello, Ruby!；<code>irb</code>进入交互解释器，适合试一条表达式，不代替可重复文件。<code>require</code> 按名称查找并记录已加载的特性；<code>require_relative</code> 以当前源文件所在目录为起点。把项目从另一个工作目录启动，库文件仍可定位，而传给 <code>File.open</code> 的相对输入路径仍相对于启动目录。命令行参数为ARGV，程序退出码用exit；本项目无gem依赖。</p><h2 id="values" tabindex="-1">对象、变量、真假与字符串 <a class="header-anchor" href="#values" aria-label="Permalink to &quot;对象、变量、真假与字符串 {#values}&quot;">​</a></h2><p>变量保存对象引用，不写静态类型声明；运行时通过方法调用决定能力。整数、字符串、类本身都是对象，但“所有东西都是对象”不代表所有操作都可以随意调用。仅false和nil为假，0、空字符串、空数组都为真，这与PHP等语言不同。<code>==</code>用于值相等的约定，<code>equal?</code>检查对象身份，Hash键依赖hash/eql?；自定义值对象要保持一致。</p><p>完整示例：</p><div class="language-ruby vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">completed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">nickname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nil</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">puts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">#{nickname </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;reader&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">#{completed}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">#{goal}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> goal</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">first</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ruby&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">second</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = first</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">second </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;test&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">length</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;zero is true&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;false&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>输出reader: 2/3、2、zero is true。赋值复制引用，dup通常浅复制，嵌套对象仍共享；freeze限制接收对象的修改，不自动深冻结其元素。<code># frozen_string_literal: true</code>让文件字符串字面量冻结，需累加字符串时可显式用可变缓冲；它不是“所有字符串全局冻结”。Symbol如:amount适合有限固定标识；String适合外部文本，不应为任意用户数据无依据转符号。</p><h2 id="methods" tabindex="-1">方法、参数、条件与模块 <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;方法、参数、条件与模块 {#methods}&quot;">​</a></h2><p>方法最后表达式通常就是返回值，显式return用于早退。关键字参数与位置Hash要区分，Ruby3之后不要依赖旧版自动转换行为。下面完整程序：</p><div class="language-ruby vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> total</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(values, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">minimum:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  values.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sum</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |value|</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    raise</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ArgumentError</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;integer required&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unless</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_a?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> minimum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  end</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">puts</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> total</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">minimum:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>输出190。<code>do ... end</code>传一个block，后续<a href="/programming/other-languages/ruby/base/intermediate/objects#blocks">block与Enumerable</a>解释yield。if/unless按真假判断，case可以用范围或类的===语义匹配，不能当字符串switch简单替换。while用于重复，each用于集合遍历；在错误恢复边界用begin/rescue/ensure，后页会给完整资源协议。</p><p>class定义实例状态和行为，@name是实例变量，@@共享类变量容易引起继承混淆；类实例变量与普通实例变量也有不同接收者。module既能组织名字又能混入行为，include/prepend会改变方法查找链，不是简单复制文本。内部依赖用require_relative，公开库需要规划命名空间，避免顶层方法意外覆盖。</p><h2 id="collections" tabindex="-1">Array、Hash、Range与空值 <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Array、Hash、Range与空值 {#collections}&quot;">​</a></h2><p>Array有序且可变，Hash映射键值并保留插入顺序，Range表示区间；<code>0...n</code>不含n，<code>0..n</code>含n。<code>map</code>返回新数组，<code>each</code>主要执行副作用，<code>select</code>过滤，<code>sum</code>聚合。命名带!的方法惯例上修改接收者或更危险，但不是语法强制；也不是所有原地修改都带!，例如Array#&lt;&lt;。</p><p>Hash.new(0)对计数器合适，因为整数不可变且通过+=写回键。<code>Hash.new([])</code>会让缺键共享同一数组而且通常不存入键，是常见陷阱；用<code>Hash.new { |h,k| h[k] = [] }</code>为每个缺键创建数组。索引缺键返回nil或默认值，fetch可要求存在并抛KeyError。报告排序应显式 <code>sort</code>。可以对同一份散列表同时检查默认对象身份、<code>key?</code> 与真实键个数，区分“读缺键产生一个值”和“读操作写入了键”。<a href="/programming/other-languages/ruby/base/basic/equality-keys">Hash 键与默认值实验</a></p><h2 id="exercise" tabindex="-1">练习与参考解法 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与参考解法 {#exercise}&quot;">​</a></h2><p>练习：判断0、&quot;&quot;、[]、nil的真假；复制包含数组的Hash后修改内层数组，预测谁变化；对同一缺键两次&lt;&lt;比较Hash.new([])与block构造；将total的minimum写成位置参数会怎样？</p><details class="details custom-block"><summary>参考解法</summary><p>只有nil为假，另外三个都真。dup默认浅复制，内部数组共享；需要独立数据时按业务逐层复制或使用不可变结构。默认共享数组会跨缺键混杂，并可能没有键被保存；block构造按键存储新数组。关键字与位置参数合同不同，调用必须匹配，不靠旧版隐式Hash转换。完整数据应用在<a href="/programming/other-languages/ruby/plus/practice/project">分类账</a>。</p></details><p>依据：<a href="https://www.ruby-lang.org/zh_cn/documentation/quickstart/" target="_blank" rel="noopener noreferrer">中文20分钟Ruby</a>、<a href="https://docs.ruby-lang.org/en/4.0/syntax_rdoc.html" target="_blank" rel="noopener noreferrer">Ruby语法</a>、<a href="https://docs.ruby-lang.org/en/4.0/Hash.html" target="_blank" rel="noopener noreferrer">Hash</a>、<a href="https://www.ruby-lang.org/en/downloads/branches/" target="_blank" rel="noopener noreferrer">维护分支</a>。</p>`,24)])])}const c=i(l,[["render",t]]);export{g as __pageData,c as default};
